/**
 * O tédio comum das visualizações 2D dos puzzles: retângulo arredondado, texto
 * posicionado, título, seta — e a paleta.
 *
 * **A paleta é a mudança de fundo em relação ao legado.** Lá cada viz trazia uma
 * dúzia de literais (`#eef2fa`, `#232a55`, `#3c4a9e`…) repetidos arquivo a
 * arquivo; aqui as cores saem dos tokens do Stratum e a intenção fica dita pelo
 * nome (`ouro` é o realce didático, `erro` é o vermelho do engano), não por um
 * número hexadecimal.
 *
 * A cena continua clara no tema escuro — `corDoTema` resolve os tokens sempre
 * pelo lado claro. Esta paleta é, portanto, um par fixo de tinta escura sobre
 * folha clara, e é o que garante que `texto` nunca chegue perto de `fundo`.
 */

import { corDoTema } from '../../../viz/canvas2d.ts';

export interface Paleta {
  readonly fundo: string;
  readonly texto: string;
  readonly fraco: string;
  readonly trilho: string;
  readonly palha: string;
  readonly azul: string;
  readonly azulClaro: string;
  readonly ouro: string;
  readonly verde: string;
  readonly erro: string;
  readonly contraste: string;
}

/** Lida a cada quadro: `corDoTema` resolve uma vez por token e guarda. */
export function paleta(): Paleta {
  return {
    fundo: corDoTema('--st-color-neutral-50', '#eef2fa'),
    texto: corDoTema('--st-color-neutral-900', '#232a55'),
    fraco: corDoTema('--st-color-neutral-600', '#5f6788'),
    trilho: corDoTema('--st-color-neutral-300', '#c3cbe8'),
    palha: corDoTema('--st-color-neutral-100', '#eef1fa'),
    azul: corDoTema('--st-color-primary-700', '#3c4a9e'),
    azulClaro: corDoTema('--st-color-primary-400', '#3aa0ff'),
    ouro: corDoTema('--st-color-warning-700', '#b07d10'),
    verde: corDoTema('--st-color-success-600', '#2f8f5c'),
    erro: corDoTema('--st-color-danger-600', '#c94a45'),
    contraste: corDoTema('--st-color-neutral-0', '#ffffff'),
  };
}

export function limitar(valor: number, minimo: number, maximo: number): number {
  return Math.max(minimo, Math.min(maximo, valor));
}

export function ptBR(n: number): string {
  return Number(n).toLocaleString('pt-BR');
}

/** Retângulo arredondado, com preenchimento e/ou contorno. */
export function retangulo(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  largura: number,
  altura: number,
  raio: number,
  // Gradiente também: é com ele que uma peça ganha volume (o lingote de ouro na
  // balança, a dívida que escoa para fora da tela).
  preenchimento?: string | CanvasGradient,
  contorno?: string,
  espessura = 1.5,
): void {
  ctx.beginPath();
  ctx.roundRect(x, y, largura, altura, raio);

  if (preenchimento !== undefined) {
    ctx.fillStyle = preenchimento;
    ctx.fill();
  }
  if (contorno !== undefined) {
    ctx.strokeStyle = contorno;
    ctx.lineWidth = espessura;
    ctx.stroke();
  }
}

export interface OpcoesTexto {
  readonly cor?: string;
  readonly peso?: number;
  readonly alinhamento?: CanvasTextAlign;
  readonly linhaBase?: CanvasTextBaseline;
}

export function texto(
  ctx: CanvasRenderingContext2D,
  conteudo: string,
  x: number,
  y: number,
  tamanho: number,
  opcoes: OpcoesTexto = {},
): void {
  ctx.fillStyle = opcoes.cor ?? paleta().texto;
  ctx.font = `${opcoes.peso ?? 400} ${tamanho}px system-ui, sans-serif`;
  ctx.textAlign = opcoes.alinhamento ?? 'center';
  ctx.textBaseline = opcoes.linhaBase ?? 'middle';
  ctx.fillText(conteudo, x, y);
}

/**
 * O título da cena, no topo — o mesmo lugar em todas as fases.
 *
 * O tamanho sai da ALTURA, mas quem estoura é a largura: "Um denário vale quanto
 * tempo de trabalho?" encostava nas duas bordas num telefone de 412 px. Então o
 * título encolhe até caber, e só até 11 px — abaixo disso o certo é encurtar a
 * frase, não continuar espremendo.
 */
export function titulo(
  ctx: CanvasRenderingContext2D,
  L: number,
  A: number,
  conteudo: string,
): void {
  const cabe = L * 0.9;
  let tamanho = limitar(A * 0.072, 13, 22);

  ctx.font = `800 ${tamanho}px system-ui, sans-serif`;
  while (tamanho > 11 && ctx.measureText(conteudo).width > cabe) {
    tamanho -= 1;
    ctx.font = `800 ${tamanho}px system-ui, sans-serif`;
  }

  texto(ctx, conteudo, L / 2, A * 0.09, tamanho, { cor: paleta().texto, peso: 800 });
}

/**
 * O veredito no rodapé da cena: verde quando a medida fecha, e o que falta
 * quando não fecha.
 */
export function rodape(
  ctx: CanvasRenderingContext2D,
  L: number,
  A: number,
  ok: boolean,
  mensagemOk: string,
  mensagemFalta: string,
  corFalta = paleta().fraco,
): void {
  texto(ctx, ok ? mensagemOk : mensagemFalta, L / 2, A * 0.95, limitar(A * 0.048, 10, 15), {
    cor: ok ? paleta().verde : corFalta,
    peso: 700,
  });
}

/**
 * Rótulo dentro de uma cápsula opaca.
 *
 * As cenas destes módulos são densas — moedas, balanças, calendários de pontos —
 * e texto solto por cima acaba encostando no desenho. A cápsula garante que o
 * rótulo continue legível onde quer que caia.
 */
export function etiqueta(
  ctx: CanvasRenderingContext2D,
  conteudo: string,
  x: number,
  y: number,
  tamanho: number,
  cor = paleta().fraco,
  peso = 700,
  opcoes: {
    /** Ponto que o rótulo nomeia; puxa uma linha-guia tracejada até ele. */
    readonly alvo?: readonly [number, number];
    readonly alinhamento?: 'left' | 'center' | 'right';
  } = {},
): void {
  ctx.font = `${peso} ${tamanho}px system-ui, sans-serif`;
  const largura = ctx.measureText(conteudo).width + tamanho * 0.9;
  const altura = tamanho * 1.75;

  const cx =
    opcoes.alinhamento === 'left'
      ? x + largura / 2
      : opcoes.alinhamento === 'right'
        ? x - largura / 2
        : x;

  if (opcoes.alvo !== undefined) {
    ctx.strokeStyle = paleta().trilho;
    ctx.lineWidth = 1.2;
    ctx.setLineDash([3, 3]);
    ctx.beginPath();
    ctx.moveTo(cx, y);
    ctx.lineTo(opcoes.alvo[0], opcoes.alvo[1]);
    ctx.stroke();
    ctx.setLineDash([]);
  }

  retangulo(
    ctx,
    cx - largura / 2,
    y - altura / 2,
    largura,
    altura,
    altura / 2,
    paleta().fundo,
    paleta().trilho,
    1,
  );
  texto(ctx, conteudo, cx, y, tamanho, { cor, peso });
}

/** Elipse achatada no chão, sob uma figura — é ela que a assenta na cena. */
export function sombraDeChao(
  ctx: CanvasRenderingContext2D,
  cx: number,
  y: number,
  largura: number,
  forca = 0.16,
): void {
  ctx.save();
  ctx.fillStyle = `rgb(35 42 85 / ${forca * 100}%)`;
  ctx.beginPath();
  ctx.ellipse(cx, y, largura, Math.max(largura * 0.16, 1.5), 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

/** Escurece uma cor `#rrggbb` — as partes em segundo plano de uma figura. */
export function escurecer(hex: string, fator = 0.22): string {
  const n = Number.parseInt(hex.slice(1), 16);
  if (!Number.isFinite(n)) return hex;

  const r = Math.round(((n >> 16) & 255) * (1 - fator));
  const g = Math.round(((n >> 8) & 255) * (1 - fator));
  const b = Math.round((n & 255) * (1 - fator));
  return `rgb(${r} ${g} ${b})`;
}

/**
 * As cores de material — metal, madeira, corda.
 *
 * Ficam fora dos tokens do tema de propósito: são a cor de uma coisa (prata é
 * prata, cobre é cobre), e é por ela que se distingue a moedinha de cobre da
 * viúva do denário de prata.
 */
export const MATERIAIS = {
  prata: '#b9c2d6',
  cobre: '#b5762f',
  bronze: '#a9702e',
  madeira: '#8a6b4a',
  madeiraClara: '#b58356',
  corda: '#8b93ad',
  cinza: '#8b93ad',
  pele: '#eabf96',
  peleEscura: '#c08a5e',
  grama: '#3ba054',
  gramaEscura: '#2c7d40',
  terra: '#d7bf95',
} as const;

/** Seta com cabeça, usada nas linhas do tempo. */
export function setaCheia(
  ctx: CanvasRenderingContext2D,
  x0: number,
  y0: number,
  x1: number,
  y1: number,
  cor: string,
  espessura: number,
): void {
  const angulo = Math.atan2(y1 - y0, x1 - x0);
  const cabeca = 7 + espessura * 1.5;

  ctx.strokeStyle = cor;
  ctx.fillStyle = cor;
  ctx.lineWidth = espessura;
  ctx.lineCap = 'round';

  ctx.beginPath();
  ctx.moveTo(x0, y0);
  ctx.lineTo(x1, y1);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - cabeca * Math.cos(angulo - 0.4), y1 - cabeca * Math.sin(angulo - 0.4));
  ctx.lineTo(x1 - cabeca * Math.cos(angulo + 0.4), y1 - cabeca * Math.sin(angulo + 0.4));
  ctx.closePath();
  ctx.fill();
}

/** Círculo cheio — o marcador de evento das linhas do tempo. */
export function disco(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  raio: number,
  cor: string,
): void {
  ctx.fillStyle = cor;
  ctx.beginPath();
  ctx.arc(x, y, raio, 0, Math.PI * 2);
  ctx.fill();
}

/**
 * O estado que a tela entrega à viz, em DOIS níveis — e confundi-los não dá erro
 * nenhum, só um desenho errado:
 *
 * - no topo, o que o usuário mexeu (`escolhido`, `valores`, `selecionados`…),
 *   copiado do puzzle por `retrato()` em `tela.ts`;
 * - em `info`, a leitura que o módulo faz disso (as contas já feitas, o `ok`).
 *
 * `escolhido` está no topo, não em `info`: as três cenas que o liam de `info`
 * ficavam sem acender a opção marcada, porque `undefined` nunca é igual a nada.
 */
export type EstadoDaViz = Readonly<Record<string, unknown>>;

export function infoDe(estado: EstadoDaViz): Readonly<Record<string, unknown>> {
  const info = estado.info;
  return info !== null && typeof info === 'object' ? (info as Record<string, unknown>) : {};
}

export function numeroDe(
  fonte: Readonly<Record<string, unknown>>,
  campo: string,
  padrao: number,
): number {
  const valor = Number(fonte[campo]);
  return Number.isFinite(valor) ? valor : padrao;
}

export function textoDe(fonte: Readonly<Record<string, unknown>>, campo: string): string {
  const valor = fonte[campo];
  return typeof valor === 'string' ? valor : '';
}
